/* oxlint-disable eslint/complexity, shadcn/no-inline-styles, anti-slop/no-known-value-widening -- FileTypeIcon keeps one branch per case, and the branded color is the per-type value of the icon table applied as an inline color. */

import { createIcon } from "@/components/icon";
import { cn } from "@/lib/utils";
import type { ComponentProps, CSSProperties } from "react";

import { classifyFile, decideFileIcon, filled } from "./file-classification";
import {
  artwork,
  brandGlyphs,
  documentGlyphs,
  fallbackIcons,
  figmaIcons,
  typeGlyphs,
} from "./file-type-artwork";
import type { FileGlyphSize } from "./file-type-artwork";

export type FileTypeIconVariant = "branded" | "monochrome";

export interface FileTypeIconProps extends Omit<
  ComponentProps<"svg">,
  "children" | "height" | "viewBox" | "width"
> {
  fileExtension?: string | null;
  fileName?: string | null;
  libraryArtifactType?: string | null;
  libraryProvider?: string | null;
  mimeType?: string | null;
  mountedLibraryFileId?: string | null;
  size?: FileGlyphSize;
  sourceMimeType?: string | null;
  sourceUrl?: string | null;
  /** `branded` (default) applies the type color. `monochrome` uses currentColor. */
  variant?: FileTypeIconVariant;
}

const glyphs = Object.fromEntries(
  Object.entries(artwork).map(([name, definition]) => [
    name,
    createIcon(definition),
  ])
);

const fallbacks = Object.fromEntries(
  Object.entries(fallbackIcons).map(([key, { brandColor, icon }]) => [
    key,
    { Icon: createIcon(icon), brandColor },
  ])
);

const figmaSizes = [12, 16, 20, 24, 32] as const;

// The component renders the Figma artwork at height and width `size`.
const figmaBySize = Object.fromEntries(
  figmaSizes.map((size) => [
    size,
    {
      dark: createIcon({
        ...figmaIcons.dark,
        canvas: { ...figmaIcons.dark.canvas, height: size, width: size },
        name: `${figmaIcons.dark.name}-${size}`,
      }),
      light: createIcon({
        ...figmaIcons.light,
        canvas: { ...figmaIcons.light.canvas, height: size, width: size },
        name: `${figmaIcons.light.name}-${size}`,
      }),
    },
  ])
);

// Text colour utilities `text-file-*` are the classes in globals.css.
const typeColorClasses: Readonly<Record<string, string>> = {
  "text-file-audio": "text-file-audio",
  "text-file-document": "text-file-document",
  "text-file-image": "text-file-image",
  "text-file-pdf": "text-file-pdf",
  "text-file-presentation": "text-file-presentation",
  "text-file-spreadsheet": "text-file-spreadsheet",
  "text-file-three-d": "text-file-three-d",
  "text-file-video": "text-file-video",
};

const BrandArtwork = ({
  artwork: key,
  className,
  size = 24,
  style,
  ...props
}: Omit<ComponentProps<"svg">, "children"> & {
  artwork: string;
  size?: FileGlyphSize;
}) => {
  const wrapper = cn(
    "inline-flex shrink-0 items-center justify-center",
    className
  );

  if (key === "figma-document") {
    const { dark: FigmaDark, light: FigmaLight } = figmaBySize[size];

    return (
      <span className={wrapper} style={style}>
        <FigmaLight {...props} className="dark:hidden" />
        <FigmaDark {...props} className="hidden dark:block" />
      </span>
    );
  }

  const name = brandGlyphs[key]?.[String(size)];
  const Glyph = name === undefined ? undefined : glyphs[name];

  return Glyph === undefined ? null : (
    <span className={wrapper} style={style}>
      <Glyph {...props} />
    </span>
  );
};

/**
 * File icon chosen from the extension, name, MIME type and source. Text and document types use a document glyph,
 * Figma and Office files use brand artwork, and the other types use a per-type
 * glyph. Variant `branded` applies the type color and `monochrome` uses
 * currentColor.
 */
export const FileTypeIcon = ({
  className,
  fileExtension,
  fileName,
  libraryArtifactType,
  libraryProvider,
  mimeType,
  mountedLibraryFileId,
  size,
  sourceMimeType,
  sourceUrl,
  style,
  variant = "branded",
  ...props
}: FileTypeIconProps) => {
  if (libraryArtifactType === "site_preview") {
    return (
      <BrandArtwork
        {...props}
        artwork="sites"
        className={className}
        size={size ?? 20}
        style={style}
      />
    );
  }

  const decision = decideFileIcon({
    fileExtension,
    fileName,
    libraryProvider,
    mimeType,
    mountedLibraryFileId,
    sourceMimeType,
    sourceUrl,
  });

  let iconKey = decision.kind === "brand" ? "file" : decision.iconKey;

  if (libraryArtifactType === "research_report") {
    iconKey = "text";
  } else if (!filled(sourceMimeType) && libraryArtifactType === "app_block") {
    iconKey = "app-block";
  } else if (
    !filled(sourceMimeType) &&
    !filled(libraryProvider) &&
    !filled(mountedLibraryFileId) &&
    filled(sourceUrl)
  ) {
    ({ iconKey } = classifyFile({ fileName, mimeType, sourceUrl }));
  }

  if (iconKey === "figma-document" || iconKey === "office-document") {
    return (
      <BrandArtwork
        {...props}
        artwork={iconKey}
        className={className}
        size={size}
        style={style}
      />
    );
  }

  if (
    iconKey === "file" &&
    decision.provider !== undefined &&
    decision.provider !== "imanage"
  ) {
    return (
      <BrandArtwork
        {...props}
        artwork={decision.provider}
        className={className}
        size={size}
        style={style}
      />
    );
  }

  const branded = variant === "branded";

  if (libraryArtifactType === "writing_block" || iconKey === "text") {
    const Glyph = glyphs[documentGlyphs[String(size ?? 20)]];

    return (
      <Glyph
        {...props}
        className={cn(branded && "text-file-document", className)}
        style={style}
      />
    );
  }

  const entry = typeGlyphs[iconKey];
  const glyphSize = size ?? 20;

  if (iconKey === "app-block" && glyphSize === 32) {
    const Glyph = glyphs[typeGlyphs["three-d"].assets["32"]];

    return <Glyph {...props} className={className} style={style} />;
  }

  const useAsset =
    entry !== undefined &&
    (glyphSize === 16 ||
      glyphSize === 32 ||
      (glyphSize === 20 && variant === "monochrome"));

  if (useAsset) {
    const Glyph = glyphs[entry.assets[String(glyphSize)]];

    const color =
      branded && entry.className !== undefined
        ? typeColorClasses[entry.className]
        : undefined;

    return <Glyph {...props} className={cn(color, className)} style={style} />;
  }

  const { Icon, brandColor } = fallbacks[iconKey] ?? fallbacks.file;

  const brandStyle: CSSProperties | undefined =
    branded && brandColor !== null ? { color: brandColor, ...style } : style;

  return (
    <Icon
      {...props}
      className={cn(iconKey === "mp4" && "size-[1em]", className)}
      style={brandStyle}
    />
  );
};

"use client";

/* oxlint-disable shadcn/no-arbitrary-values -- The thumbnail takes the radius of its parent with rounded-[inherit]. */

import {
  ViewerCloseIcon,
  ViewerDownloadIcon,
} from "@/components/carousel/icons";
import { Banner } from "@/components/ui/banner";
import { Button, Spinner } from "@/components/ui/button";
import { useToast } from "@/components/ui/toast";
import { cn } from "@/lib/utils";
import { useRef, useState } from "react";
import type { ComponentProps } from "react";

import { ImagePreviewDialog } from "./image-preview-dialog";

export interface LightboxImage {
  readonly src: string;
  readonly title?: string;
}

export interface ImageLightboxProps {
  images: readonly LightboxImage[];
  /** Runs the download. Resolve to `false` or reject for "Could not download image". */
  onDownload?: (image: LightboxImage) => Promise<boolean> | boolean;
  onOpenChange: (open: boolean) => void;
  open?: boolean;
  selectedIndex?: number;
}

/**
 * A thumbnail fills its box: size-full, the parent's radius, a 1px default
 * border and object-cover.
 */
export const ImageThumbnail = ({
  alt,
  className,
  ...props
}: ComponentProps<"img"> & { alt: string }) => (
  // The src is a caller URL, so the Next image optimizer does not apply.
  // oxlint-disable-next-line nextjs/no-img-element
  <img
    {...props}
    alt={alt}
    className={cn(
      "size-full rounded-[inherit] border border-border object-cover",
      className
    )}
  />
);

/**
 * The image lightbox: Image {n} alternative text, a "{current} of {total}"
 * status, a retry callout when an image fails to load, a download action and
 * Close viewer, over the image preview dialog.
 */
export const ImageLightbox = ({
  images,
  onDownload,
  onOpenChange,
  open = true,
  selectedIndex = 0,
}: ImageLightboxProps) => {
  const toast = useToast();
  const imageRef = useRef<HTMLImageElement>(null);
  const [index, setIndex] = useState(selectedIndex);
  const [failed, setFailed] = useState<readonly string[]>([]);
  const [loaded, setLoaded] = useState<string | null>(null);
  const [downloading, setDownloading] = useState(false);

  const image = images[index];

  if (image === undefined) {
    return null;
  }

  const alt = image.title ?? `Image ${index + 1}`;
  const hasFailed = failed.includes(image.src);
  const ready = loaded === image.src && !hasFailed;

  const download = async () => {
    setDownloading(true);

    let ok = true;

    try {
      ok = (await onDownload?.(image)) ?? true;
    } catch {
      ok = false;
    }

    setDownloading(false);

    if (!ok) {
      toast.danger("Could not download image");
    }
  };

  return (
    <ImagePreviewDialog
      footer={
        images.length > 1 ? (
          <output className="shrink-0 select-none">
            {`${index + 1} of ${images.length}`}
          </output>
        ) : undefined
      }
      imageRef={imageRef}
      open={open}
      onNext={
        index >= images.length - 1
          ? undefined
          : () => {
              setIndex(index + 1);
            }
      }
      onOpenChange={onOpenChange}
      onPrevious={
        index === 0
          ? undefined
          : () => {
              setIndex(index - 1);
            }
      }
    >
      <div className="absolute inset-x-0 top-0 z-30 flex items-center justify-between gap-3 px-4 py-2">
        <div className="flex min-w-0 items-center gap-2">
          <span className="min-w-0 truncate text-sm font-medium text-text">
            {alt}
          </span>
        </div>
        <div className="flex items-center gap-1" role="toolbar">
          {onDownload === undefined ? null : (
            <Button
              aria-label="Download image"
              disabled={downloading || !ready}
              uniform
              onClick={() => {
                void download();
              }}
            >
              <ViewerDownloadIcon aria-hidden />
            </Button>
          )}
          <Button
            aria-label="Close viewer"
            autoFocus
            uniform
            onClick={() => {
              onOpenChange(false);
            }}
          >
            <ViewerCloseIcon aria-hidden />
          </Button>
        </div>
      </div>
      <div className="flex size-full items-center justify-center">
        {hasFailed ? (
          <div className="m-auto select-none">
            <Banner
              content="Couldn't load this image"
              layout="vertical"
              primaryCtaText="Try again"
              // The callout is announced as a status.
              // oxlint-disable-next-line jsx-a11y/prefer-tag-over-role
              role="status"
              variant="callout"
              onPrimaryCtaClick={() => {
                setFailed(failed.filter((src) => src !== image.src));
              }}
            />
          </div>
        ) : (
          <>
            {ready ? null : (
              <div className="m-auto">
                <Spinner />
              </div>
            )}
            {/* The lightbox shows a caller URL, so the Next image optimizer does not apply. */}
            {/* oxlint-disable-next-line nextjs/no-img-element */}
            <img
              ref={imageRef}
              alt={alt}
              className={cn(
                "max-h-full max-w-full object-contain select-none",
                !ready && "hidden"
              )}
              key={image.src}
              referrerPolicy="no-referrer"
              src={image.src}
              onError={() => {
                setFailed([...failed, image.src]);
              }}
              onLoad={() => {
                setLoaded(image.src);
              }}
            />
          </>
        )}
      </div>
    </ImagePreviewDialog>
  );
};

"use client";

import {
  ChevronLeft20Icon,
  ChevronRight20Icon,
} from "@/components/carousel/icons";
import { Button } from "@/components/ui/button";
import { Dialog, DialogTitle } from "@/components/ui/dialog";
import { useRef } from "react";
import type {
  KeyboardEvent,
  MouseEvent,
  PointerEvent,
  ReactNode,
  RefObject,
} from "react";

/** A click that moves less than this many pixels counts as a click, not a drag. */
const CLICK_TRAVEL_LIMIT = 5;

const INTERACTIVE_TARGETS =
  'button, a, input, textarea, select, video, iframe, [role="toolbar"], [role="menu"], [role="menuitem"], [data-ck-annotation-control], [data-ck-image-preview-composer], [contenteditable="true"]';

export interface ImagePreviewDialogProps {
  /** Disables the navigation buttons and makes the image area inert. */
  busy?: boolean;
  /** The image area. */
  children?: ReactNode;
  /** An editing mode in the image area turns off arrow keys and click dismissal. */
  editing?: boolean;
  /** Content under the image row, for example the position counter. */
  footer?: ReactNode;
  /** The image element. A click inside its box never dismisses. */
  imageRef?: RefObject<HTMLElement | null>;
  /** Space under the footer for a composer (the `px-6 pb-6` row). */
  composer?: ReactNode;
  /** Label of the next button. The default is "Next image". */
  nextLabel?: string;
  /** Keeps the next button but disables it, as the video lightbox does at the last item. */
  nextDisabled?: boolean;
  onNext?: () => void;
  onOpenChange: (open: boolean) => void;
  onPrevious?: () => void;
  open?: boolean;
  /** Keeps the previous button but disables it, as the video lightbox does at the first item. */
  previousDisabled?: boolean;
  /** Label of the previous button. The default is "Previous image". */
  previousLabel?: string;
  /** The screen reader only title. The default is "Image preview". */
  title?: string;
}

const isDismissTarget = (
  event: MouseEvent<HTMLElement>,
  imageRef: RefObject<HTMLElement | null> | undefined
) => {
  const { target } = event;

  if (
    !(target instanceof Element) ||
    !event.currentTarget.contains(target) ||
    target.closest(INTERACTIVE_TARGETS)
  ) {
    return false;
  }

  const box = imageRef?.current?.getBoundingClientRect();

  return (
    box === undefined ||
    event.clientX < box.left ||
    event.clientX > box.right ||
    event.clientY < box.top ||
    event.clientY > box.bottom
  );
};

const hasModifier = (event: KeyboardEvent<HTMLElement>) =>
  event.altKey || event.ctrlKey || event.metaKey || event.shiftKey;

/**
 * The image preview dialog: a flex
 * column with the image area, w-18 gutters for Previous image and Next image,
 * and a footer row. ArrowLeft and ArrowRight navigate, and a click that moves
 * less than 5px outside the image dismisses it.
 */
export const ImagePreviewDialog = ({
  busy = false,
  children,
  composer,
  editing = false,
  footer,
  imageRef,
  nextDisabled = false,
  nextLabel = "Next image",
  onNext,
  onOpenChange,
  onPrevious,
  open = true,
  previousDisabled = false,
  previousLabel = "Previous image",
  title = "Image preview",
}: ImagePreviewDialogProps) => {
  const pressStart = useRef<{ x: number; y: number } | null>(null);

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const inToolbar =
      event.target instanceof Element &&
      event.target.closest('[role="toolbar"]') !== null;

    if (
      busy ||
      editing ||
      event.defaultPrevented ||
      hasModifier(event) ||
      event.nativeEvent.isComposing ||
      inToolbar
    ) {
      return;
    }

    let navigate: (() => void) | undefined;

    if (event.key === "ArrowLeft" && !previousDisabled) {
      navigate = onPrevious;
    } else if (event.key === "ArrowRight" && !nextDisabled) {
      navigate = onNext;
    }

    if (navigate === undefined) {
      return;
    }

    event.preventDefault();
    navigate();
  };

  const onPointerDownCapture = (event: PointerEvent<HTMLDivElement>) => {
    pressStart.current =
      !editing &&
      event.isPrimary &&
      event.button === 0 &&
      isDismissTarget(event, imageRef)
        ? { x: event.clientX, y: event.clientY }
        : null;
  };

  const onPointerMoveCapture = (event: PointerEvent<HTMLDivElement>) => {
    const start = pressStart.current;

    if (
      start !== null &&
      Math.hypot(event.clientX - start.x, event.clientY - start.y) >
        CLICK_TRAVEL_LIMIT
    ) {
      pressStart.current = null;
    }
  };

  const onClick = (event: MouseEvent<HTMLDivElement>) => {
    const pressed = pressStart.current !== null;
    pressStart.current = null;

    if (
      !editing &&
      pressed &&
      event.detail > 0 &&
      !event.defaultPrevented &&
      isDismissTarget(event, imageRef)
    ) {
      onOpenChange(false);
    }
  };

  return (
    <Dialog
      contentProps={{
        "aria-describedby": undefined,
        onClick,
        // The component stops the built-in outside dismissal, so only the click rule above closes it.
        onInteractOutside: (event) => {
          event.preventDefault();
        },
        onKeyDown,
        onPointerCancelCapture: () => {
          pressStart.current = null;
        },
        onPointerDownCapture,
        onPointerMoveCapture,
      }}
      open={open}
      showDialogClose={false}
      variant="image"
      viewportSized
      onOpenChange={onOpenChange}
    >
      <DialogTitle className="sr-only">{title}</DialogTitle>
      <div className="relative flex h-full min-h-0 flex-col">
        <div className="flex min-h-0 flex-1">
          <div className="pointer-events-none relative z-30 flex w-18 shrink-0 items-center justify-center">
            {onPrevious === undefined ? null : (
              <Button
                aria-label={previousLabel}
                className="pointer-events-auto"
                disabled={busy || previousDisabled}
                uniform
                onClick={onPrevious}
              >
                <ChevronLeft20Icon aria-hidden />
              </Button>
            )}
          </div>
          <div
            className="@container relative min-h-0 min-w-0 flex-1"
            inert={busy}
          >
            {children}
          </div>
          <div className="pointer-events-none relative z-30 flex w-18 shrink-0 items-center justify-center">
            {onNext === undefined ? null : (
              <Button
                aria-label={nextLabel}
                className="pointer-events-auto"
                disabled={busy || nextDisabled}
                uniform
                onClick={onNext}
              >
                <ChevronRight20Icon aria-hidden />
              </Button>
            )}
          </div>
        </div>
        <div className="relative z-30 shrink-0">
          {footer === undefined ? null : (
            <div className="flex min-w-0 items-center justify-center gap-3 p-4 text-sm">
              {footer}
            </div>
          )}
          {composer === undefined ? null : (
            <div
              className="px-6 pb-6"
              data-ck-image-preview-composer
              inert={busy}
            >
              {composer}
            </div>
          )}
        </div>
      </div>
    </Dialog>
  );
};

/* oxlint-disable eslint/complexity, eslint/no-control-regex, eslint/prefer-named-capture-group -- The provider parser keeps its validation rules in one pass. */

const providers = new Set([
  "box",
  "dropbox",
  "google_drive",
  "sharepoint",
  "onedrive",
  "imanage",
]);

const externalId =
  /^external-([a-z0-9][a-z0-9-]*):(?:account:((?:[A-Za-z0-9._~-]|%[0-9A-F]{2})+):)?(?:(file|folder|collection):(\S+)|root)$/u;

const googleId = /^[A-Za-z0-9_-]{5,512}$/u;
const encodedComponent = /^[A-Za-z0-9_-]{1,683}$/u;
const decodedComponent = /^[A-Za-z0-9._!~:-]{1,512}$/u;

const validAccount = (value: string, strict: boolean) => {
  if (value.length === 0 || value.length > 1536) {
    return false;
  }

  try {
    const decoded = decodeURIComponent(value);

    const encoded = encodeURIComponent(decoded).replaceAll(
      /[!'()*]/gu,
      (char) => `%${(char.codePointAt(0) ?? 0).toString(16).toUpperCase()}`
    );

    return (
      decoded.length > 0 &&
      (strict
        ? !/^\p{White_Space}|\p{White_Space}$/u.test(decoded)
        : decoded === decoded.trim()) &&
      !/[\u0000-\u001F\u007F]/u.test(decoded) &&
      new TextEncoder().encode(decoded).length <= 512 &&
      encoded === value
    );
  } catch {
    return false;
  }
};

const validBase64 = (value: string) => {
  if (!encodedComponent.test(value)) {
    return false;
  }

  try {
    const base64 = value.replaceAll("-", "+").replaceAll("_", "/");
    const decoded = atob(base64 + "=".repeat((4 - (base64.length % 4)) % 4));

    return (
      decodedComponent.test(decoded) &&
      btoa(decoded)
        .replaceAll("+", "-")
        .replaceAll("/", "_")
        .replace(/[=]+$/u, "") === value
    );
  } catch {
    return false;
  }
};

const fromExternalId = (id: string): string | undefined => {
  if (id.startsWith("external-imanage:")) {
    const match = /^external-imanage:[a-f0-9]{64}:document:([^:]+)$/u.exec(id);

    if (match?.[1] !== undefined && validAccount(match[1], true)) {
      return /^[^!]+![0-9]+\.[0-9]+$/u.test(decodeURIComponent(match[1]))
        ? "imanage"
        : undefined;
    }

    return undefined;
  }

  if (id.startsWith("external-onedrive:file:v3:")) {
    const parts = id.split(":");

    return id.length <= 2100 &&
      parts.length === 7 &&
      (parts[3] === "personal" || parts[3] === "business") &&
      parts.slice(4).every(validBase64)
      ? "onedrive"
      : undefined;
  }

  const match = externalId.exec(id);

  if (!match) {
    return undefined;
  }

  const [, slug, account, kind, nativeId] = match;

  if (!slug || kind !== "file" || !nativeId) {
    return undefined;
  }

  const strict = slug === "box" || slug === "dropbox" || slug === "sharepoint";

  if (
    account !== undefined &&
    !(slug === "gdrive"
      ? /^[A-Za-z0-9_-]+$/u.test(account)
      : validAccount(account, strict))
  ) {
    return undefined;
  }

  if (
    account !== undefined &&
    strict &&
    (new TextEncoder().encode(id).length > 4096 ||
      new TextEncoder().encode(nativeId).length > 2048 ||
      /[\u0000-\u001F\u007F]/u.test(nativeId))
  ) {
    return undefined;
  }

  if (slug === "sharepoint") {
    const parts = nativeId.startsWith("v1:item:")
      ? nativeId.slice(8).split(":")
      : [];

    return parts.length === 2 && parts.every(validBase64)
      ? "sharepoint"
      : undefined;
  }

  if (nativeId.length > 512) {
    return undefined;
  }

  if (slug === "box" && /^[1-9][0-9]*$/u.test(nativeId)) {
    return "box";
  }

  if (
    slug === "dropbox" &&
    nativeId.length <= 256 &&
    /^id:[A-Za-z0-9_:-]+$/u.test(nativeId)
  ) {
    return "dropbox";
  }

  if (slug === "gdrive" && googleId.test(nativeId)) {
    return "google_drive";
  }

  return undefined;
};

export const mountedFileProvider = (
  libraryProvider?: string | null,
  mountedLibraryFileId?: string | null
) => {
  const id =
    mountedLibraryFileId?.startsWith("file-library:") === true
      ? mountedLibraryFileId.slice(13)
      : mountedLibraryFileId;

  if (id?.startsWith("external-") === true) {
    const provider = fromExternalId(id);

    return libraryProvider === null ||
      libraryProvider === undefined ||
      libraryProvider === provider
      ? provider
      : undefined;
  }

  return libraryProvider !== null &&
    libraryProvider !== undefined &&
    providers.has(libraryProvider)
    ? libraryProvider
    : undefined;
};

